    const uniforms=all(`SELECT uc.id uniform_id,uc.name,uc.size,SUM(CASE um.movement_type WHEN 'DELIVERY' THEN um.quantity WHEN 'RETURN' THEN -um.quantity WHEN 'LOSS' THEN -um.quantity ELSE 0 END) held FROM uniform_movements um JOIN uniform_catalog uc ON uc.id=um.uniform_id WHERE um.organization_id=:o AND um.employee_id=:e GROUP BY uc.id,uc.name,uc.size HAVING ABS(held)>0.0001 ORDER BY uc.name,uc.size`,{o,e:e.id});
