  r.post('/patrimonio/:id/excluir',async(req,res,ctx,q,p)=>{if(!C.requireAdmin(ctx,res))return;const b=await C.parseBody(req);if(!C.csrfOk(ctx,b))return C.send(res,403,C.errorPage('Sessão inválida',''));const o=ctx.user.organization_id,a=get('SELECT * FROM assets WHERE id=:id AND organization_id=:o',{id:p.id,o});if(!a)return C.redirect(res,'/patrimonio');const allocations=all('SELECT * FROM asset_allocations WHERE asset_id=:id AND organization_id=:o',{id:a.id,o}),maint=all('SELECT * FROM asset_maintenances WHERE asset_id=:id AND organization_id=:o',{id:a.id,o});if(allocations.length||maint.length)return C.redirect(res,C.flashUrl(`/patrimonio/${a.id}`,`Não é possível excluir definitivamente este patrimônio porque há ${allocations.length} alocação(ões) e ${maint.length} manutenção(ões) no histórico. O bloqueio preserva o log dos colaboradores. Você pode editar os dados e as alocações; se uma alocação estiver errada, exclua a alocação específica.`,'warn'));run('DELETE FROM assets WHERE id=:id AND organization_id=:o',{id:a.id,o});C.audit(ctx,req,'DELETE','assets',a.id,a,null);C.redirect(res,C.flashUrl('/patrimonio','Patrimônio sem histórico operacional excluído pelo administrador.'));});
